WITH exploded AS (SELECT id, service, host, log_ts, level, latency_ms, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS attr_key, value) SELECT id, service, host, log_ts, level, latency_ms, attr_key, value, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY attr_key), 4) AS latency_ms_share, MAX(latency_ms) OVER (PARTITION BY service ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS latency_ms_max_1h, FIRST_VALUE(latency_ms, TRUE) OVER (PARTITION BY service, attr_key ORDER BY latency_ms, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_latency_ms, MAX(latency_ms) OVER (PARTITION BY level) AS level_max_latency_ms FROM exploded;
